    if (!chosen) return undefined;
    return readFileSync(chosen, 'utf8');
  } catch {
    return undefined;
  }
}

/**
 * Build the `codex login --with-api-key` arg list. The key itself is piped over
 * stdin (spawnSync { input }), never placed on the argv.
 *
 * @returns {string[]}
 */
export function buildCodexLoginArgs() {
  return ['login', '--with-api-key'];
}

/** True when $CODEX_HOME/auth.json (default ~/.codex/auth.json) is a ChatGPT subscription login. */
function hasChatGptAuth() {
  try {
    const home = process.env.CODEX_HOME || join(homedir(), '.codex');
    return JSON.parse(readFileSync(join(home, 'auth.json'), 'utf8')).auth_mode === 'chatgpt';
  } catch {
    return false;
  }
}

